import{_ as t,o as a,c as r,ag as s}from"./chunks/framework.BIas3y6W.js";const p=JSON.parse('{"title":"CS [2xxx] Building Apps with AI","description":"","frontmatter":{"source":"SYLLABUS.md"},"headers":[],"relativePath":"SYLLABUS.md","filePath":"SYLLABUS.md"}'),i={name:"SYLLABUS.md"};function o(n,e,d,l,h,c){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="cs-2xxx-building-apps-with-ai" tabindex="-1">CS [2xxx] Building Apps with AI <a class="header-anchor" href="#cs-2xxx-building-apps-with-ai" aria-label="Permalink to &quot;CS [2xxx] Building Apps with AI&quot;">​</a></h1><p>3 credits</p><p>[Semester and year, as scheduled]</p><h2 id="instructor" tabindex="-1">Instructor <a class="header-anchor" href="#instructor" aria-label="Permalink to &quot;Instructor&quot;">​</a></h2><ul><li><strong>Name:</strong> [name]</li><li><strong>Email:</strong> [email]</li><li><strong>Phone:</strong> [phone]</li><li><strong>Office hours:</strong> [days, times and place]</li><li><strong>Class meetings:</strong> [days, times and room]; two 75-minute studios a week, Studio A (Learn &amp; build) and Studio B (Workshop)</li></ul><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p>One programming course in any language, such as CS 1112, CS 1120, CS 2120 or another department&#39;s programming course; equivalent programming experience; or instructor permission. No experience with web development, the terminal or git is needed, and <a href="./setup/python-to-javascript.html">From Python to JavaScript</a> covers what changes for students who know Python. CS students who have completed CS 3383 Software Engineering should take <a href="https://boyu-zhang-uoi.github.io/engineering-software-with-ai/" target="_blank" rel="noreferrer">Engineering Software with AI</a> (CS [4xxx]/[5xxx]) instead.</p><h2 id="course-description" tabindex="-1">Course Description <a class="header-anchor" href="#course-description" aria-label="Permalink to &quot;Course Description&quot;">​</a></h2><p>This course teaches students from any major to build and ship web apps by directing AI tools, and to apply the engineering habits that make AI-written software trustworthy. Topics include how large language models write code; HTML, CSS and JavaScript; prompting; version control with git and GitHub; specifications with testable acceptance criteria; automated testing; reading and debugging code; APIs, servers and secret keys; AI agents and code review through pull requests; database access rules; web security; and deployment. Students learn by building, in two hands-on studios a week. Studio A (Learn &amp; build) introduces the week&#39;s concepts through short demonstrations and a guided build that students complete in class. Studio B (Workshop) is supervised work time on that week&#39;s lab and projects, with instructor feedback and peer review. They begin with a chat assistant and finish with an AI agent working in their own repository, shipping a series of projects to the public web with free tools and ending with a capstone of their own choosing. The course introduces vibe coding and its limits, and it emphasizes writing the specification before the prompt, checking AI output, protecting secrets and data, and being able to explain every line of code without AI.</p><h2 id="required-textbooks-and-materials" tabindex="-1">Required Textbooks and Materials <a class="header-anchor" href="#required-textbooks-and-materials" aria-label="Permalink to &quot;Required Textbooks and Materials&quot;">​</a></h2><p>No textbook.</p><h2 id="learning-outcomes" tabindex="-1">Learning Outcomes <a class="header-anchor" href="#learning-outcomes" aria-label="Permalink to &quot;Learning Outcomes&quot;">​</a></h2><p>At the end of this course, students will be able to:</p><ul><li>Build working web software, from single-file pages to a full-stack app, by directing chat assistants, app builders and coding agents through a repeatable workflow (the <a href="./resources/safe-loop.html">Safe Loop</a>), and switch to a fallback tool without losing work.</li><li>Develop a one-page specification with user stories and testable acceptance criteria before building.</li><li>Evaluate AI output rather than trust it: write the check first, test normal and edge cases, and read the diff.</li><li>Explain every part of the code they submit, and debug a failing program by reading its error messages, without AI.</li><li>Apply version control with git and GitHub as a safety net, committing, comparing, reverting, branching and reviewing changes through pull requests.</li><li>Deploy projects to the public web and present them clearly while protecting privacy and secrets, which includes keeping API keys on the server, enforcing database access rules, checking dependencies and containing AI agents.</li></ul><h2 id="course-outline" tabindex="-1">Course Outline <a class="header-anchor" href="#course-outline" aria-label="Permalink to &quot;Course Outline&quot;">​</a></h2><p>The course follows a standard 16-week semester. Weeks 1–15 have two studios a week; week 16 is finals week, when students present their capstones in the scheduled final exam period.</p><table tabindex="0"><thead><tr><th>Week</th><th>Topic</th><th>Key concepts</th></tr></thead><tbody><tr><td>1</td><td><a href="./weeks/01-hello-vibe-coding/">Hello, Vibe Coding</a></td><td>Vibe coding and its limits; how an LLM writes code; what a web page is (HTML, CSS, JavaScript); the AI-use labels; privacy settings and the safety contract</td></tr><tr><td>2</td><td><a href="./weeks/02-ship-your-page/">Ship Your Page</a></td><td>Publishing on GitHub Pages; commits as save points; what a public repository exposes; three prompting habits; accessibility from the start; <code>PROMPTS.md</code>; personal AI-use rules</td></tr><tr><td>3</td><td><a href="./weeks/03-prompting-and-save-points/">Prompting &amp; Save Points</a></td><td>Prompts as directions (goal, context, constraints, done when); the context window; small steps and the two-strikes rule; commits; <code>Assisted-by:</code> lines</td></tr><tr><td>4</td><td><a href="./weeks/04-undo-compare-explain/">Undo, Compare, Explain</a></td><td>Rolling back to a save point; comparing two models against a written check; explaining code you did not write; rewriting weak prompts; a first automated test</td></tr><tr><td>5</td><td><a href="./weeks/05-spec-first/">Spec First</a></td><td>The spec as the prompt for the whole project; user stories and priorities; testable acceptance criteria; out of scope; the Goldfish test; app builders</td></tr><tr><td>6</td><td><a href="./weeks/06-spec-to-app/">From Spec to App</a></td><td>Judging apps against written criteria; app-builder lock-in and credits; rules in a module of pure functions; writing the test first; previewing before you commit</td></tr><tr><td>7</td><td><a href="./weeks/07-read-and-debug/">Read It, Debug It</a></td><td>Anatomy of a web app; reading error messages and stack traces; a debugging method (reproduce, isolate, hypothesize, test, fix, verify); edge cases</td></tr><tr><td>8</td><td><a href="./weeks/08-own-it/">Own It</a></td><td>Git history as a debugging tool (<code>log</code>, <code>diff</code>, <code>revert</code>); writing code by hand while the AI reviews; testing the project&#39;s logic</td></tr><tr><td>9</td><td><a href="./weeks/09-apis-and-secrets/">APIs &amp; Secrets</a></td><td>Requests, responses and APIs; the browser is public; API keys kept on the server; checking every input on the server; the system prompt as product design</td></tr><tr><td>10</td><td><a href="./weeks/10-servers-and-deployment/">Servers &amp; Deployment</a></td><td>Serverless functions; deploying to a production URL; one API format, many providers; proving the key stays secret; revoking a leaked key; calling public APIs</td></tr><tr><td>11</td><td><a href="./weeks/11-agents/">How Agents Work</a></td><td>An agent as an LLM in a loop with tools; context as working memory; plans, approvals and sandboxes; how agents fail; <code>AGENTS.md</code>; credits as a budget</td></tr><tr><td>12</td><td><a href="./weeks/12-pull-requests/">Pull Requests &amp; Agent Code</a></td><td>Branches and pull requests; reviewing agent code that is almost right; checking changes to the tests; testing your instructions; chart and external-API features</td></tr><tr><td>13</td><td><a href="./weeks/13-data-and-access/">Data &amp; Access Rules</a></td><td>Authentication versus authorization; Supabase; grants and row-level security (RLS); attacking a practice table; recent data leaks</td></tr><tr><td>14</td><td><a href="./weeks/14-security-and-review/">Security &amp; Review</a></td><td>Cross-site scripting; secrets in git history; risky packages; prompt injection; a one-paragraph threat model; changing one&#39;s own code with the AI off; human and AI review</td></tr><tr><td>15</td><td><a href="./weeks/15-ship-it/">Ship It</a></td><td>The definition of done; polish; accessibility; honest known issues; rehearsing the final presentation; where the field is going; ethics, law and disclosure</td></tr><tr><td>16</td><td><a href="./weeks/16-final-presentations/">Final Presentations</a> (finals week)</td><td>A five-minute presentation and live demo of each capstone in the scheduled final exam period; the capstone is due</td></tr></tbody></table><h2 id="grading" tabindex="-1">Grading <a class="header-anchor" href="#grading" aria-label="Permalink to &quot;Grading&quot;">​</a></h2><h3 id="assessment" tabindex="-1">Assessment <a class="header-anchor" href="#assessment" aria-label="Permalink to &quot;Assessment&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Component</th><th>Weight</th></tr></thead><tbody><tr><td>Assignments</td><td>20%</td></tr><tr><td>Labs</td><td>20%</td></tr><tr><td>Project 1</td><td>15%</td></tr><tr><td>Project 2</td><td>15%</td></tr><tr><td>Final project (capstone)</td><td>30%</td></tr></tbody></table><p>Assignments and labs are graded on completion and effort. Projects 1 and 2 and the final project are graded with the rubrics in the <a href="./assessment/">assessment guide</a>.</p><h3 id="final-examination" tabindex="-1">Final Examination <a class="header-anchor" href="#final-examination" aria-label="Permalink to &quot;Final Examination&quot;">​</a></h3><p>There is no final examination. In the scheduled final exam period, each student or pair gives a five-minute presentation of their capstone with a live demo. The capstone is due at the start of that period: the app working at its public URL, and its repository with the README and the <code>PROMPTS.md</code> log.</p><h3 id="performance-standards-and-grading-policy" tabindex="-1">Performance Standards and Grading Policy <a class="header-anchor" href="#performance-standards-and-grading-policy" aria-label="Permalink to &quot;Performance Standards and Grading Policy&quot;">​</a></h3><p>Letter grades are A (90–100%), B (80–89%), C (70–79%), D (60–69%) and F (below 60%).</p><h3 id="assignments" tabindex="-1">Assignments <a class="header-anchor" href="#assignments" aria-label="Permalink to &quot;Assignments&quot;">​</a></h3><ul><li>Assignments (weeks 1–15), due before the next week&#39;s Studio A. They include the <a href="./projects/home-page.html">home page</a> in weeks 1–4, weekly reflections and two peer reviews.</li><li>Labs: in-class work in every studio, and a short exit ticket written without AI in weeks 1–14.</li><li><a href="./projects/project-1-useful-tool.html">Project 1, A Tool I&#39;d Actually Use</a> (weeks 5–8).</li><li><a href="./projects/ai-micro-app.html">Project 2, An AI Micro-App</a> (weeks 9–10): a small deployed app that calls an AI model through a server function, with the API key kept on the server.</li><li>The final project, or <a href="./projects/capstone.html">capstone</a> (weeks 11–16): a deployed full-stack app of the student&#39;s choice, built with an AI agent, alone or in a pair.</li></ul><p>Reflections, peer reviews and exit tickets are submitted on Canvas, not in a repository.</p><h3 id="late-work-policy" tabindex="-1">Late Work Policy <a class="header-anchor" href="#late-work-policy" aria-label="Permalink to &quot;Late Work Policy&quot;">​</a></h3><p>Each student has two grace tokens; each extends one deadline by 48 hours, with no reason needed. Other late work loses 10% per day and scores zero after three days. Tokens do not apply to live events (studios, exit tickets and the final presentations); missed live events follow the <a href="./assessment/#absences-and-make-up-work">make-up rules</a>.</p><h2 id="ai-use" tabindex="-1">AI Use <a class="header-anchor" href="#ai-use" aria-label="Permalink to &quot;AI Use&quot;">​</a></h2><p>AI tools are a required part of this course, and grades depend on whether students can explain their work, not on how much AI they used. Each task is labelled AI on, AI limited or AI off; exit tickets, reflections and peer reviews are always AI off. AI help is disclosed in each project&#39;s <code>PROMPTS.md</code> log and in an <code>Assisted-by: [tool]</code> line on AI-assisted commits. The full rules are in the <a href="./assessment/#ai-use-policy">AI use policy</a> and the <a href="./setup/safety-contract.html">safety contract</a>.</p><h2 id="academic-honesty" tabindex="-1">Academic Honesty <a class="header-anchor" href="#academic-honesty" aria-label="Permalink to &quot;Academic Honesty&quot;">​</a></h2><p>Academic dishonesty, including cheating and plagiarism, is not tolerated at the University of Idaho. Plagiarism means presenting another&#39;s work as your own: copying it, quoting or paraphrasing it without attribution, or buying it. In this course it also includes using AI on a task marked AI off and hiding AI help that the <a href="#ai-use">AI Use</a> rules ask you to disclose. Suspected cases are handled under the Student Code of Conduct (FSH 2300) and reported to the Dean of Students.</p><h2 id="university-of-idaho-classroom-learning-civility-clause" tabindex="-1">University of Idaho Classroom Learning Civility Clause <a class="header-anchor" href="#university-of-idaho-classroom-learning-civility-clause" aria-label="Permalink to &quot;University of Idaho Classroom Learning Civility Clause&quot;">​</a></h2><p>Everyone in this course, including students, instructors, teaching assistants and guests, is expected to treat one another with respect and civility. If you feel our classroom does not meet this standard, please talk to me during office hours, or contact the <a href="https://www.uidaho.edu/student-resources/dean-of-students" target="_blank" rel="noreferrer">Dean of Students</a>, the <a href="https://www.uidaho.edu/student-resources/health-wellness/counseling-mental-health-center" target="_blank" rel="noreferrer">Counseling and Mental Health Center</a> or the <a href="https://www.uidaho.edu/civil-rights" target="_blank" rel="noreferrer">Office of Civil Rights and Investigations</a>.</p><h2 id="center-for-disability-access-and-resources" tabindex="-1">Center for Disability Access and Resources <a class="header-anchor" href="#center-for-disability-access-and-resources" aria-label="Permalink to &quot;Center for Disability Access and Resources&quot;">​</a></h2><p>Students with disabilities who need accommodations should contact the Center for Disability Access and Resources (CDAR) at <a href="https://www.uidaho.edu/cdar" target="_blank" rel="noreferrer">www.uidaho.edu/cdar</a> or 208-885-6307. Accommodations must be approved through CDAR before they are implemented.</p><h2 id="firearms" tabindex="-1">Firearms <a class="header-anchor" href="#firearms" aria-label="Permalink to &quot;Firearms&quot;">​</a></h2><p>The University of Idaho bans firearms from its property, with limited exceptions. Holders of a valid Idaho enhanced concealed carry license may carry a firearm only if it stays concealed at all times; displaying it, other than in necessary self-defense, violates University policy. Report firearms on University property to local law enforcement by calling 911.</p><h2 id="student-resources" tabindex="-1">Student Resources <a class="header-anchor" href="#student-resources" aria-label="Permalink to &quot;Student Resources&quot;">​</a></h2><p>The University of Idaho offers <a href="https://www.uidaho.edu/student-resources" target="_blank" rel="noreferrer">student resources</a> to support your learning, including:</p><ul><li><strong>SI-PASS:</strong> <a href="https://www.uidaho.edu/student-resources/academic-support/peer-assisted-study-sessions" target="_blank" rel="noreferrer">peer-led study sessions</a> for difficult courses.</li><li><strong>Library:</strong> databases and research help from librarians on the <a href="https://www.lib.uidaho.edu/" target="_blank" rel="noreferrer">UofI Library website</a>.</li><li><strong>Technology help:</strong> the <a href="https://www.uidaho.edu/student-resources/technical-support" target="_blank" rel="noreferrer">IT Service Desk</a>, 208-885-4357, <a href="https://support.uidaho.edu/" target="_blank" rel="noreferrer">support.uidaho.edu</a>.</li><li><strong>Writing support:</strong> one-on-one help at the <a href="https://www.uidaho.edu/student-resources/academic-support/writing-center" target="_blank" rel="noreferrer">Writing Center</a>, 208-885-6644.</li><li><strong>Student Success Program:</strong> free tutoring Sunday to Thursday, 2:00 to 10:00 pm, in the Wallace Residence Center basement, open to all students.</li><li><strong>Vandal Food Pantry:</strong> <a href="https://www.uidaho.edu/student-resources/dean-of-students/basic-needs-food-insecurity-resources" target="_blank" rel="noreferrer">free food and hygiene items</a>, open to all.</li><li><strong>Green Dot Safety Program:</strong> <a href="https://www.uidaho.edu/student-resources/health-wellness/violence-prevention-center" target="_blank" rel="noreferrer">bystander intervention training</a>; <a href="mailto:greendot@uidaho.edu" target="_blank" rel="noreferrer">greendot@uidaho.edu</a>.</li></ul><h2 id="uofi-moscow-land-acknowledgement" tabindex="-1">UofI Moscow Land Acknowledgement <a class="header-anchor" href="#uofi-moscow-land-acknowledgement" aria-label="Permalink to &quot;UofI Moscow Land Acknowledgement&quot;">​</a></h2><p>UofI Moscow is located on the homelands of the Nimiipuu (Nez Perce), Palus (Palouse) and Schitsu&#39;umsh (Coeur d&#39;Alene) tribes. We extend gratitude to the indigenous people that call this place home, since time immemorial. UofI recognizes that it is our academic responsibility to build relationships with the indigenous people to ensure integrity of tribal voices.</p>',45)])])}const g=t(i,[["render",o]]);export{p as __pageData,g as default};
